(d/'element.json').write_text(json.dumps({'schema':'rhetis.design-library-element-source/1','contract':'steps.sequence@1','registrations':{},'tokenDefaults':{'--crossrail-step-count':'4'}},indent=2)+'\n')
def step(mark,name,note,icon=None,col=False):return '<div class="step"><span class="mark">'+(f'<span class="icon" data-icon="{icon}"></span>' if icon and col else '')+mark+'</span><p class="name">'+(f'<span class="icon" data-icon="{icon}"></span>' if icon and not col else '')+name+'</p><p class="note">'+note+'</p></div>'
def write(name,classes,items,mini):
 (d/f'fixtures/{name}.html').write_text(f'<!-- min:{mini} -->\n<div class="steps {classes}" data-el="crossrail-steps" style="grid-column:1 / span 12;grid-row:1 / span 6">'+''.join(items)+'</div>\n')
write('base-a','',[step('01','물량 분류','반품 봉투를 도착 구역별로 나누고 회수 차량에 싣기 전 수량을 대조합니다.'),step('02','담당 배차','기사별 잔여 운행 거리를 살펴 가장 가까운 회수 지점부터 순번을 지정합니다.'),step('03','수령 확인','봉인 상태를 확인한 뒤 접수 번호와 서명 기록을 묶어 보관합니다.')],'8x4')
write('base-b','',[step(str(i+1).zfill(2),name,note) for i,(name,note) in enumerate([('반출 신청','정비실에서 부품 묶음을 신청하면 요청 시각과 배송 구역이 자동 저장됩니다.'),('재고 점검','선반별 잔량을 대조하고 보관 기한이 먼저 끝나는 묶음부터 출고합니다.'),('포장 및 검수','파손 위험이 높은 부품은 완충재를 추가하고 봉인 후 무게를 다시 잽니다.'),('차량 탑재','운송장과 적재 구역을 맞춘 다음 기사가 배차 시간을 확인합니다.'),('창고 인계','도착 지점에서 수량을 세고 누락 건을 당일 접수 목록으로 되돌립니다.')])],'9x4')
write('replica-10','',[step('FLOW 1','접수','운송 중 발생한 손상 신고를 모아 포장 상태와 회수 구역을 나눕니다. 접수 시각을 대조해 먼저 처리할 묶음을 정합니다.','inbox'),step('FLOW 2','배정','남아 있는 운행 거리를 살펴 지점별 회수 담당을 정합니다. 필요한 상자와 완충재 수량을 산정해 차량별로 나눠 싣습니다.','route'),step('FLOW 3','검수','도착한 포장물을 열어 부품 번호와 파손 위치를 대조합니다. 사진 기록과 담당자 서명을 함께 보관해 재발송 누락을 막습니다.','scan-line'),step('FLOW 4','인계','수리실의 인수 시각을 확인하고 교체 부품의 보관 선반을 지정합니다. 출고에 필요한 운송장과 봉인 자재도 미리 갖춥니다.','package-check')],'8x5')
write('replica-13','col',[step(str(i+1).zfill(2),name,note,icon,True) for i,(name,note,icon) in enumerate([('분류','도착한 수리 물품을 장비 종류별로 묶고 담당 창구를 지정해 접수 누락을 막습니다.','boxes'),('진단','작동 기록과 점검 항목을 대조한 뒤 교체가 필요한 부품의 범위를 정합니다.','clipboard-check'),('수선','분해한 부품의 상태를 기록하고 새 부품을 장착한 뒤 통전 시험을 진행합니다.','wrench'),('반출','검사표와 운송장을 묶어 보관하며 수령자의 서명 기록이 들어오면 접수를 닫습니다.','truck')])],'10x4')
